import XCTest
import Darwin
@testable import SapflowBroadcaster

/// Generated bytes only. These tests establish file/receipt lifecycle, never
/// media playability, AVAssetWriter completion or physical storage durability.
final class RecordingCatalogueTests: XCTestCase {
    private var scratch: URL!
    override func setUpWithError() throws {
        scratch = FileManager.default.temporaryDirectory.appendingPathComponent("sapflow-recording-test-" + UUID().uuidString)
        try FileManager.default.createDirectory(at: scratch, withIntermediateDirectories: false)
    }
    override func tearDownWithError() throws { try FileManager.default.removeItem(at: scratch) }
    private func directory(_ name: String = "recordings") -> URL { scratch.appendingPathComponent(name) }
    private func finished(_ catalogue: RecordingCatalogue, bytes: Int = 129_001,
                          outcome: RecordingCatalogue.Completion = .finalised) throws -> RecordingCatalogue.Entry {
        let writer = try catalogue.begin(identity: catalogue.newShow(profile: .sd480p30).nextIdentity())
        try Data((0..<bytes).map { UInt8($0 % 127) }).write(to: writer.fileURL, options: .withoutOverwriting)
        try writer.complete(durationMs: 1500, outcome: outcome)
        XCTAssertTrue(writer.cleanupComplete)
        return try XCTUnwrap(catalogue.scan().first { $0.segmentID == writer.identity.segmentID })
    }
    private func media(_ entry: RecordingCatalogue.Entry, _ root: URL) -> URL {
        root.appendingPathComponent("Sapflow-\(entry.segmentID).mov")
    }
    private func receipt(_ entry: RecordingCatalogue.Entry, _ root: URL) -> URL {
        root.appendingPathComponent("Sapflow-\(entry.segmentID).receipt.json")
    }
    private func assertFailure(_ expected: RecordingCatalogue.Failure, _ body: () throws -> Void, file: StaticString = #filePath, line: UInt = #line) {
        XCTAssertThrowsError(try body(), file: file, line: line) { XCTAssertEqual($0 as? RecordingCatalogue.Failure, expected, file: file, line: line) }
    }
    func testShowOrderAndImmutableProfileHaveDistinctSegmentIdentities() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let show = catalogue.newShow(profile: .sd480p30), a = try show.nextIdentity(), b = try show.nextIdentity()
        XCTAssertEqual(a.showID, b.showID); XCTAssertEqual(a.segmentIndex, 0); XCTAssertEqual(b.segmentIndex, 1)
        XCTAssertNotEqual(a.segmentID, b.segmentID); XCTAssertEqual(b.profileID, "480p30")
        assertFailure(.unsafe) { _ = try RecordingCatalogue.Identity(segmentID: "../unsafe", showID: a.showID, segmentIndex: 0, profileID: a.profileID) }
        assertFailure(.unsafe) { _ = try RecordingCatalogue.Identity(segmentID: a.segmentID + "\n", showID: a.showID, segmentIndex: 0, profileID: a.profileID) }
    }
    func testCompletedReceiptSurvivesRestartAndExactExport() throws {
        var catalogue: RecordingCatalogue? = try RecordingCatalogue(root: directory())
        let selected = try finished(catalogue!)
        XCTAssertEqual(selected.state, .finalised); XCTAssertEqual(selected.durationMs, 1500)
        try catalogue!.close(); catalogue = nil
        let reopened = try RecordingCatalogue(root: directory()); defer { try? reopened.close() }
        let fresh = try XCTUnwrap(reopened.scan().first)
        XCTAssertEqual(fresh.identity, selected.identity)
        let export = try reopened.openExport(entry: fresh); defer { try? export.close() }
        var result = Data()
        XCTAssertEqual(try export.copy(write: { XCTAssertLessThanOrEqual($0.count, 65_536); result.append($0) }), fresh.bytes)
        XCTAssertEqual(result, try Data(contentsOf: media(fresh, directory())))
        XCTAssertFalse(export.cleanupComplete)
        try export.close(); XCTAssertTrue(export.cleanupComplete)
    }
    func testCompletedContainerWithPriorLossRemainsExplicitlyIncomplete() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let selected = try finished(catalogue, outcome: .incomplete)
        XCTAssertEqual(selected.state, .incomplete)
        assertFailure(.ineligible) { _ = try catalogue.openExport(entry: selected) }
        let export = try catalogue.openExport(entry: selected, allowUnverified: true); defer { try? export.close() }
        XCTAssertEqual(try export.copy(write: { _ in }), selected.bytes)
        XCTAssertEqual(try catalogue.scan().first?.state, .incomplete)
    }
    func testLiveWriterCancellationAndMissingFileNeverPromoteCompletion() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let writer = try catalogue.begin(identity: catalogue.newShow(profile: .hd720p30).nextIdentity())
        XCTAssertEqual(try catalogue.scan().first?.state, .writing)
        XCTAssertTrue(catalogue.cleanupRetained); XCTAssertFalse(catalogue.cleanupUncertain)
        assertFailure(.busy) { try catalogue.checkRecordingCapacity() }
        assertFailure(.busy) { try catalogue.close() }
        writer.cancel(); try writer.ownersClosed()
        XCTAssertFalse(catalogue.cleanupRetained)
        XCTAssertEqual(try catalogue.scan().first?.state, .orphanUnverified)
        assertFailure(.cancelled) { try writer.complete(durationMs: 1, outcome: .finalised) }
    }
    func testAbandonedWritingReceiptBecomesRawIncompleteAfterActualOwnerClose() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let writer = try catalogue.begin(identity: catalogue.newShow(profile: .hd720p30).nextIdentity())
        try Data([1, 2, 3]).write(to: writer.fileURL, options: .withoutOverwriting)
        writer.cancel(); try writer.ownersClosed()
        let entry = try XCTUnwrap(catalogue.scan().first)
        XCTAssertEqual(entry.state, .incomplete)
        assertFailure(.ineligible) { _ = try catalogue.openExport(entry: entry) }
        let export = try catalogue.openExport(entry: entry, allowUnverified: true); defer { try? export.close() }
        XCTAssertEqual(try export.copy(write: { _ in }), 3)
    }
    func testLegacyDocumentsRemainUnverifiedUnmovedAndRequireExplicitExport() throws {
        let legacy = directory("documents"); try FileManager.default.createDirectory(at: legacy, withIntermediateDirectories: false)
        let name = "Sapflow-\(UUID().uuidString).mov", url = legacy.appendingPathComponent(name)
        try Data([7, 8, 9]).write(to: url)
        let catalogue = try RecordingCatalogue(root: directory(), legacyRoot: legacy); defer { try? catalogue.close() }
        let entry = try XCTUnwrap(catalogue.scan().first)
        XCTAssertEqual(entry.location, .legacyDocuments); XCTAssertEqual(entry.state, .orphanUnverified); XCTAssertNil(entry.identity)
        assertFailure(.ineligible) { _ = try catalogue.openExport(entry: entry) }
        let export = try catalogue.openExport(entry: entry, allowUnverified: true); defer { try? export.close() }
        XCTAssertEqual(try export.copy(write: { _ in }), 3)
        XCTAssertEqual(try Data(contentsOf: url), Data([7, 8, 9]))
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: legacy.path), [name])
    }
    func testCorruptMissingOversizedAndDuplicateKeyReceiptsNeverPromoteFiles() throws {
        for variant in 0..<4 {
            let root = directory("case\(variant)"); let catalogue = try RecordingCatalogue(root: root); defer { try? catalogue.close() }
            let entry = try finished(catalogue)
            switch variant {
            case 0: try FileManager.default.removeItem(at: receipt(entry, root))
            case 1: try Data("{}".utf8).write(to: receipt(entry, root))
            case 2: try Data(repeating: 32, count: 4097).write(to: receipt(entry, root))
            default:
                let bytes = try Data(contentsOf: receipt(entry, root)), text = try XCTUnwrap(String(data: bytes, encoding: .utf8))
                try Data(("{\"version\":1," + text.dropFirst()).utf8).write(to: receipt(entry, root))
            }
            XCTAssertEqual(try catalogue.scan().first?.state, .orphanUnverified)
        }
    }
    func testReplacedSameSizeMediaIsNotAdoptedByItsOldFinalReceipt() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let entry = try finished(catalogue)
        try FileManager.default.moveItem(at: media(entry, directory()), to: directory().appendingPathComponent("preserved-original"))
        try Data(repeating: 0, count: Int(entry.bytes)).write(to: media(entry, directory()))
        let unverified = try XCTUnwrap(catalogue.scan().first)
        XCTAssertEqual(unverified.state, .orphanUnverified)
        XCTAssertNil(unverified.identity); XCTAssertNil(unverified.durationMs)
        assertFailure(.changed) { _ = try catalogue.openExport(entry: entry) }
    }
    func testSymlinkHardlinkAndRootSubstitutionAreRefused() throws {
        for variant in 0..<2 {
            let root = directory("links\(variant)"), catalogue = try RecordingCatalogue(root: root); defer { try? catalogue.close() }
            let entry = try finished(catalogue), original = media(entry, root), other = scratch.appendingPathComponent("target\(variant)")
            try FileManager.default.moveItem(at: original, to: other)
            if variant == 0 { try FileManager.default.createSymbolicLink(at: original, withDestinationURL: other) }
            else { try FileManager.default.linkItem(at: other, to: original) }
            assertFailure(.unsafe) { _ = try catalogue.scan() }
            assertFailure(.unsafe) { _ = try catalogue.openExport(entry: entry) }
        }
        let root = directory("changed"), catalogue = try RecordingCatalogue(root: root); defer { try? catalogue.close() }
        try FileManager.default.moveItem(at: root, to: directory("preserved"))
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: false)
        assertFailure(.changed) { _ = try catalogue.scan() }
    }
    func testChangedReceiptRefusesAnOldPickerBeforeAnyCopy() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let old = try finished(catalogue)
        try Data("{}".utf8).write(to: receipt(old, directory()))
        assertFailure(.changed) { _ = try catalogue.openExport(entry: old) }
        XCTAssertFalse(catalogue.cleanupRetained); XCTAssertFalse(catalogue.cleanupUncertain)
    }
    func testCopyRefusesTruncationGrowthAndPathReplacementWithoutDeletingOriginal() throws {
        for variant in 0..<3 {
            let root = directory("copy\(variant)"), catalogue = try RecordingCatalogue(root: root); defer { try? catalogue.close() }
            let entry = try finished(catalogue), export = try catalogue.openExport(entry: entry); defer { try? export.close() }
            var first = true
            assertFailure(.changed) {
                _ = try export.copy(write: { chunk in
                    XCTAssertLessThanOrEqual(chunk.count, 65_536)
                    if first {
                        first = false
                        switch variant {
                        case 0:
                            let handle = try FileHandle(forWritingTo: self.media(entry, root)); try handle.truncate(atOffset: 1); try handle.close()
                        case 1:
                            let handle = try FileHandle(forWritingTo: self.media(entry, root)); try handle.seekToEnd(); try handle.write(contentsOf: Data([1])); try handle.close()
                        default:
                            try FileManager.default.moveItem(at: self.media(entry, root), to: root.appendingPathComponent("preserved"))
                            try Data(repeating: 0, count: Int(entry.bytes)).write(to: self.media(entry, root))
                        }
                    }
                })
            }
            XCTAssertTrue(FileManager.default.fileExists(atPath: media(entry, root).path))
        }
    }
    func testCancellationAndDestinationFailurePreserveSourceAndReleaseOnlyOnClose() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let entry = try finished(catalogue), export = try catalogue.openExport(entry: entry)
        assertFailure(.cancelled) { _ = try export.copy(write: { _ in }, cancelled: { true }) }
        XCTAssertFalse(export.cleanupComplete); assertFailure(.busy) { try catalogue.checkRecordingCapacity() }
        try export.close(); XCTAssertTrue(export.cleanupComplete)
        let next = try catalogue.openExport(entry: entry)
        assertFailure(.io) { _ = try next.copy(write: { _ in throw RecordingCatalogue.Failure.io }) }
        try next.close()
        XCTAssertEqual(try Data(contentsOf: media(entry, directory())).count, Int(entry.bytes))
        XCTAssertFalse(catalogue.cleanupRetained)
    }
    func testCloseCannotRaceAnInFlightReadAndRepeatedCloseCannotRetryDescriptor() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let entry = try finished(catalogue), export = try catalogue.openExport(entry: entry)
        XCTAssertEqual(try export.copy(write: { _ in self.assertFailure(.busy) { try export.close() } }), entry.bytes)
        try export.close(); try export.close()
        assertFailure(.closed) { _ = try export.copy(write: { _ in }) }
        XCTAssertFalse(catalogue.cleanupUncertain)
    }
    func testCombinedCapacityAndDirectoryBoundAreVisibleWithoutDeletingAnything() throws {
        let root = directory(), legacy = directory("documents")
        try FileManager.default.createDirectory(at: legacy, withIntermediateDirectories: false)
        let catalogue = try RecordingCatalogue(root: root, legacyRoot: legacy); defer { try? catalogue.close() }
        for index in 0..<256 {
            let folder = index < 128 ? root : legacy
            try Data([1]).write(to: folder.appendingPathComponent("Sapflow-\(UUID().uuidString).mov"))
        }
        XCTAssertEqual(try catalogue.scan().count, 256)
        assertFailure(.capacity) { try catalogue.checkRecordingCapacity() }
        XCTAssertFalse(catalogue.cleanupRetained)
        try Data([1]).write(to: legacy.appendingPathComponent("Sapflow-\(UUID().uuidString).mov"))
        assertFailure(.capacity) { _ = try catalogue.scan() }
        let second = try RecordingCatalogue(root: directory("entry-bound")); defer { try? second.close() }
        for index in 0..<1025 { try Data().write(to: directory("entry-bound").appendingPathComponent("unrelated-\(index)")) }
        assertFailure(.capacity) { _ = try second.scan() }
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: directory("entry-bound").path).count, 1025)
    }
    #if os(macOS)
    func testActualLifetimeFlockSurvivesScansAndRefusedOwnersUntilRealClose() throws {
        let root = directory(), catalogue = try RecordingCatalogue(root: root)
        func childCanLock() throws -> Bool {
            let process = Process(), output = Pipe(), done = DispatchSemaphore(value: 0)
            process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
            process.arguments = ["python3", "-c", "import os,fcntl,sys\nf=os.open(sys.argv[1],os.O_RDONLY)\ntry:\n fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);print('open')\nexcept BlockingIOError:\n print('blocked')\nos.close(f)", root.path]
            process.standardOutput = output; process.standardError = output; process.terminationHandler = { _ in done.signal() }
            try process.run()
            if done.wait(timeout: .now() + 3) != .success {
                process.terminate(); _ = done.wait(timeout: .now() + 1)
                if process.isRunning { kill(process.processIdentifier, SIGKILL); _ = done.wait(timeout: .now() + 1) }
                throw RecordingCatalogue.Failure.io
            }
            guard process.terminationStatus == 0 else { throw RecordingCatalogue.Failure.io }
            let bytes = try XCTUnwrap(try output.fileHandleForReading.read(upToCount: 128))
            return String(data: bytes, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines) == "open"
        }
        XCTAssertFalse(try childCanLock())
        for _ in 0..<3 {
            _ = try catalogue.scan()
            assertFailure(.busy) { _ = try RecordingCatalogue(root: root) }
            XCTAssertFalse(try childCanLock())
        }
        let writer = try catalogue.begin(identity: catalogue.newShow(profile: .sd480p30).nextIdentity())
        assertFailure(.busy) { try catalogue.close() }
        XCTAssertFalse(try childCanLock()); writer.cancel(); try writer.ownersClosed()
        try catalogue.close(); XCTAssertTrue(catalogue.cleanupComplete); XCTAssertTrue(try childCanLock())
    }
    #endif
    func testUnknownWriterCleanupIsStickyAndHealthyBusyDoesNotPoison() throws {
        let catalogue = try RecordingCatalogue(root: directory())
        let writer = try catalogue.begin(identity: catalogue.newShow(profile: .sd480p30).nextIdentity())
        assertFailure(.busy) { try catalogue.checkRecordingCapacity() }
        XCTAssertFalse(catalogue.cleanupUncertain)
        writer.retainUncertainCleanup()
        XCTAssertTrue(catalogue.cleanupUncertain); XCTAssertTrue(catalogue.cleanupRetained)
        writer.cancel(); assertFailure(.closed) { try writer.ownersClosed() }
        assertFailure(.busy) { try catalogue.close() }
        XCTAssertFalse(writer.cleanupComplete)
        // The isolated test executable owns this deliberately retained FD and
        // exits immediately after the suite. No media or child process remains.
    }
    func testActualInputCloseWithFailedReceiptCannotReleaseOrRetryNumericDescriptor() throws {
        var fault = false, closes = 0
        let catalogue = try RecordingCatalogue(root: directory(), closeFileDescriptor: { fd in
            closes += 1
            let result = Darwin.close(fd)
            return fault ? -1 : result
        })
        let entry = try finished(catalogue), export = try catalogue.openExport(entry: entry)
        fault = true
        assertFailure(.io) { try export.close() }
        let actualCloses = closes
        XCTAssertTrue(catalogue.cleanupUncertain); XCTAssertTrue(catalogue.cleanupRetained)
        XCTAssertFalse(export.cleanupComplete)
        assertFailure(.closed) { try export.close() }
        XCTAssertEqual(closes, actualCloses)
        assertFailure(.closed) { _ = try catalogue.openExport(entry: entry) }
        assertFailure(.busy) { _ = try RecordingCatalogue(root: directory()) }
    }
    func testDurableReceiptFailureNeverFinalisesOrReleasesItsUnknownOwner() throws {
        let root = directory(), catalogue = try RecordingCatalogue(root: root)
        let writer = try catalogue.begin(identity: catalogue.newShow(profile: .hd720p30).nextIdentity())
        try Data([1, 2, 3]).write(to: writer.fileURL, options: .withoutOverwriting)
        XCTAssertEqual(chmod(root.path, 0o500), 0)
        defer { chmod(root.path, 0o700) }
        XCTAssertThrowsError(try writer.complete(durationMs: 10, outcome: .finalised))
        XCTAssertTrue(catalogue.cleanupUncertain); XCTAssertFalse(writer.cleanupComplete)
        XCTAssertEqual(chmod(root.path, 0o700), 0)
        let bytes = try Data(contentsOf: root.appendingPathComponent("Sapflow-\(writer.identity.segmentID).receipt.json"))
        XCTAssertTrue(String(data: bytes, encoding: .utf8)?.contains("\"state\":\"writing\"") == true)
        writer.cancel(); XCTAssertThrowsError(try writer.ownersClosed())
        XCTAssertEqual(try Data(contentsOf: writer.fileURL), Data([1, 2, 3]))
    }
    func testFailedMetadataCloseBeforeExportReturnsStillRetainsItsExactOwner() throws {
        var fault = false
        let catalogue = try RecordingCatalogue(root: directory(), closeFileDescriptor: { fd in
            let result = Darwin.close(fd)
            return fault ? -1 : result
        })
        let entry = try finished(catalogue)
        fault = true
        assertFailure(.io) { _ = try catalogue.openExport(entry: entry) }
        XCTAssertTrue(catalogue.cleanupUncertain); XCTAssertTrue(catalogue.cleanupRetained)
        assertFailure(.closed) { try catalogue.checkRecordingCapacity() }
        XCTAssertEqual(try Data(contentsOf: media(entry, directory())).count, Int(entry.bytes))
    }
    func testOldWriterCallbacksCannotReleaseOrCompleteItsSuccessor() throws {
        let catalogue = try RecordingCatalogue(root: directory()); defer { try? catalogue.close() }
        let show = catalogue.newShow(profile: .hd720p30)
        let old = try catalogue.begin(identity: show.nextIdentity())
        old.cancel(); try old.ownersClosed()
        let fresh = try catalogue.begin(identity: show.nextIdentity())
        try old.ownersClosed()
        assertFailure(.cancelled) { try old.complete(durationMs: 1, outcome: .finalised) }
        XCTAssertTrue(catalogue.cleanupRetained); XCTAssertFalse(catalogue.cleanupUncertain)
        assertFailure(.busy) { try catalogue.checkRecordingCapacity() }
        XCTAssertEqual(try catalogue.scan().first { $0.segmentID == fresh.identity.segmentID }?.state, .writing)
        fresh.cancel(); try fresh.ownersClosed()
    }
    func testCatalogueCloseDoesNotReportCleanupBeforeActualDescriptorClose() throws {
        let entered = DispatchSemaphore(value: 0), release = DispatchSemaphore(value: 0), done = DispatchSemaphore(value: 0)
        let catalogue = try RecordingCatalogue(root: directory(), closeFileDescriptor: { fd in
            entered.signal()
            guard release.wait(timeout: .now() + 3) == .success else { return -1 }
            return Darwin.close(fd)
        })
        DispatchQueue.global().async { try? catalogue.close(); done.signal() }
        defer { release.signal(); _ = done.wait(timeout: .now() + 3) }
        XCTAssertEqual(entered.wait(timeout: .now() + 3), .success)
        XCTAssertFalse(catalogue.cleanupComplete); XCTAssertTrue(catalogue.cleanupRetained)
        assertFailure(.closed) { _ = try catalogue.scan() }
        release.signal()
        XCTAssertEqual(done.wait(timeout: .now() + 3), .success)
        XCTAssertTrue(catalogue.cleanupComplete); XCTAssertFalse(catalogue.cleanupRetained)
    }
    func testExistingPrivateRootMustDenyOtherUsersWhileLegacyKeepsReadOnlyDiscoveryPolicy() throws {
        let root = directory(), legacy = directory("documents")
        try FileManager.default.createDirectory(at: root, withIntermediateDirectories: false)
        try FileManager.default.createDirectory(at: legacy, withIntermediateDirectories: false)
        XCTAssertEqual(chmod(root.path, 0o755), 0)
        assertFailure(.unsafe) { _ = try RecordingCatalogue(root: root) }
        XCTAssertEqual(try FileManager.default.contentsOfDirectory(atPath: root.path).count, 0)
        XCTAssertEqual(chmod(root.path, 0o700), 0); XCTAssertEqual(chmod(legacy.path, 0o755), 0)
        let catalogue = try RecordingCatalogue(root: root, legacyRoot: legacy); defer { try? catalogue.close() }
        XCTAssertEqual(try catalogue.scan().count, 0)
        XCTAssertEqual(chmod(root.path, 0o755), 0)
        assertFailure(.unsafe) { _ = try catalogue.scan() }
        XCTAssertEqual(chmod(root.path, 0o700), 0)
        XCTAssertEqual(try catalogue.scan().count, 0)
    }
}
